.cn-input:not(.cn-input-group-input):focus-visible,.cn-textarea:not(.cn-input-group-textarea):focus-visible,.cn-select-trigger:focus-visible,.cn-native-select:focus-visible,.cn-input-group:not(.cn-command-input-group):focus-within{border-color:var(--ring);box-shadow:var(--inputs-shadow);outline:3px solid color-mix(in srgb,var(--ring) 28%,transparent);outline-offset:2px}
