.cn-card,.cn-attachment{box-shadow:var(--data-display-shadow);border-width:var(--data-display-border-width)}.cn-table-container{box-shadow:var(--data-display-shadow);border-width:var(--data-display-border-width)}.cn-item{box-shadow:none}
