.cn-card:focus-within,.cn-table-container:focus-within{border-color:var(--ring)}
/* overlays */
.cn-dialog-content,.cn-alert-dialog-content,.cn-sheet-content,.cn-popover-content,.cn-hover-card-content,.cn-select-content,.cn-dropdown-menu-content,.cn-context-menu-content,.cn-menubar-content,.cn-combobox-content{border-width:var(--overlays-border-width);box-shadow:var(--overlays-shadow)}
