/* feedback */
.cn-alert,.cn-toast{border-width:var(--feedback-border-width);box-shadow:var(--feedback-shadow)}
.cn-alert{border-inline-start:var(--feedback-accent-width) solid var(--secondary)}.cn-toast{border-inline-start:var(--feedback-accent-width) solid var(--accent)}.cn-progress-track{background-color:var(--secondary)}.cn-progress-indicator{background-color:var(--primary)}
